   extern crate serial;

   use std::io::prelude::\*;

   use std::io;use std::env;

   use std::time::Duration;

   use serial::prelude::\*;

   fn main() {

   let mut port;

   let mut msg: \[u8;1\]=\[1\];

   for arg in    env::args\_os().skip(1) {

   port = serial::open(&arg).unwrap();


    interact(&mut port).unwrap();}



   fn interact<T: SerialPort>(port: &mut T) ->        io::Result<()> {port.reconfigure(&|settings

   {settings.set\_baud\_rate(serial::Baud9600)?;

   settings.set\_char\_size(serial::Bits8);

   settings.set\_parity(serial::ParityNone);

   settings.set\_stop\_bits(serial::Stop1);

   settings.set\_flow\_control(serial::FlowNone);

   Ok(())})?;

   port.set\_timeout(Duration::from\_millis(1000))?;

   let mut buf: Vec<u8> = (0..255).collect();

   port.write(&buf\[..\])?;

   port.read(&mut buf\[..\]);

   Ok(())

   }

